<?php
require_once __DIR__.'/config.php'; require_auth(); require_permission('manage_appointments'); ensure_extended_schema(); $pdo=db();$u=current_user();$error='';$flash=get_flash();
$custId=0;if($u['role']==='customer'){$st=$pdo->prepare("SELECT id FROM customers WHERE user_id=:u");$st->execute([':u'=>$u['id']]);$custId=(int)$st->fetchColumn();}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';$id=(int)($_POST['id']??0);if($a==='save'){$cid=$u['role']==='customer'?$custId:(int)$_POST['customer_id'];$vid=(int)$_POST['vehicle_id'];$d=$_POST['appointment_date']??'';$t=$_POST['appointment_time']??'';$sid=(int)($_POST['service_id']??0)?:null;if(!$cid||!$vid||!$d||!$t)$error='أكمل بيانات الموعد.';else{$pdo->prepare("INSERT INTO appointments(customer_id,vehicle_id,appointment_date,appointment_time,service_id,notes,status,created_by) VALUES(:c,:v,:d,:t,:s,:n,'pending',:by)")->execute([':c'=>$cid,':v'=>$vid,':d'=>$d,':t'=>$t,':s'=>$sid,':n'=>trim($_POST['notes']??''),':by'=>$u['id']]);log_audit('create','appointments',(int)$pdo->lastInsertId(),'إنشاء موعد صيانة');set_flash('success','تم إنشاء الموعد.');header('Location: appointments.php');exit;} }elseif($a==='status'&&$id){$ns=$_POST['status'];if(!in_array($ns,['confirmed','completed','cancelled'],true))$ns='pending';$pdo->prepare("UPDATE appointments SET status=:s WHERE id=:id" . ($u['role']==='customer'?' AND customer_id='.$custId:''))->execute([':s'=>$ns,':id'=>$id]);log_audit('update_status','appointments',$id,'تغيير حالة الموعد إلى '.$ns);set_flash('success','تم تحديث الموعد.');header('Location: appointments.php');exit;}}
$customers=$u['role']==='customer'?[]:$pdo->query("SELECT id,full_name FROM customers ORDER BY full_name")->fetchAll();$vehicles=$u['role']==='customer'?$pdo->query("SELECT id,make,model,plate_number FROM vehicles WHERE customer_id=".$custId)->fetchAll():$pdo->query("SELECT id,customer_id,make,model,plate_number FROM vehicles ORDER BY id DESC")->fetchAll();$services=$pdo->query("SELECT id,name FROM services WHERE status='active' ORDER BY name")->fetchAll();
if($u['role']==='customer'){$st=$pdo->prepare("SELECT a.*,v.make,v.model,v.plate_number,s.name service_name FROM appointments a JOIN vehicles v ON v.id=a.vehicle_id LEFT JOIN services s ON s.id=a.service_id WHERE a.customer_id=:c ORDER BY a.appointment_date DESC,a.appointment_time DESC");$st->execute([':c'=>$custId]);$rows=$st->fetchAll();}else{$rows=$pdo->query("SELECT a.*,c.full_name,v.make,v.model,v.plate_number,s.name service_name FROM appointments a JOIN customers c ON c.id=a.customer_id JOIN vehicles v ON v.id=a.vehicle_id LEFT JOIN services s ON s.id=a.service_id ORDER BY a.appointment_date DESC,a.appointment_time DESC")->fetchAll();}
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>المواعيد</title><link rel="stylesheet" href="style.css"></head><body class="dashboard-body"><div class="dashboard-wrapper"><main class="main-content" style="width:100%"><header class="topbar"><h2 class="page-title">📅 مواعيد الصيانة</h2><a class="btn btn-outline" href="dashboard.php">العودة</a></header><div class="content-container"><?php if($flash):?><div class="alert alert-<?=clean($flash['type'])?>"><?=clean($flash['message'])?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=clean($error)?></div><?php endif;?><div class="card mb-4"><div class="card-body"><form method="post" class="form-grid" style="grid-template-columns:repeat(auto-fit,minmax(160px,1fr))"><?=csrf_field()?><input type="hidden" name="action" value="save"><?php if($u['role']!=='customer'):?><select class="form-control" name="customer_id" required><option value="">العميل</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=clean($c['full_name'])?></option><?php endforeach;?></select><?php endif;?><select class="form-control" name="vehicle_id" required><option value="">السيارة</option><?php foreach($vehicles as $v):?><option value="<?=$v['id']?>"><?=clean($v['make'].' '.$v['model'].' - '.$v['plate_number'])?></option><?php endforeach;?></select><input class="form-control" type="date" name="appointment_date" required><input class="form-control" type="time" name="appointment_time" required><select class="form-control" name="service_id"><option value="">الخدمة</option><?php foreach($services as $s):?><option value="<?=$s['id']?>"><?=clean($s['name'])?></option><?php endforeach;?></select><input class="form-control" name="notes" placeholder="ملاحظات"><button class="btn btn-primary">حجز موعد</button></form></div></div><div class="card"><div class="card-body" style="overflow-x:auto"><table class="data-table"><thead><tr><th>التاريخ</th><th>العميل</th><th>السيارة</th><th>الخدمة</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=clean($r['appointment_date'].' '.$r['appointment_time'])?></td><td><?=clean($r['full_name']??'أنا')?></td><td><?=clean($r['make'].' '.$r['model'].' - '.$r['plate_number'])?></td><td><?=clean($r['service_name']??'-')?></td><td><?=status_badge($r['status'])?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" onchange="this.form.submit()" class="form-control"><option value="">تغيير الحالة</option><option value="confirmed">تأكيد</option><option value="completed">مكتمل</option><option value="cancelled">إلغاء</option></select></form></td></tr><?php endforeach;?></tbody></table></div></div></div></main></div></body></html>